using System;using BepInEx.Configuration;using UnityEngine;
namespace InFalsusStudio.Gameplay {
 internal static class GameplayOptions {
  internal static ConfigEntry<double> Latency,VisualLatency;internal static ConfigEntry<int> BufferFrames;
  internal static ConfigEntry<float> Sensitivity,Music,Master,Attack,Sustain;internal static ConfigEntry<bool> Sounds,HoldAttack;internal static ConfigEntry<int> SkyAttack;
  internal static void Bind(ConfigFile config){VisualLatency=config.Bind("Gameplay","VisualLatencyMs",0d,new ConfigDescription("Visual-only timing adjustment in chart ms.",new AcceptableValueRange<double>(-200,200)));BufferFrames=config.Bind("Gameplay","AudioBufferFrames",256,new ConfigDescription("FMOD gameplay block size; applied next session.",new AcceptableValueList<int>(128,256,512,1024)));Latency=config.Bind("Gameplay","LatencyMs",0d,new ConfigDescription("Gameplay-only timing delay in ms. Positive values delay the gameplay timeline relative to music; editor and export timing are unchanged.",new AcceptableValueRange<double>(-1000,1000)));Sensitivity=config.Bind("Gameplay","MouseSensitivity",1f,new ConfigDescription("Multiplier applied to OS-processed mouse motion only in built-in gameplay.",new AcceptableValueRange<float>(.1f,5f)));Music=Volume(config,"MusicVolume",1);Master=Volume(config,"HitMaster",.65f);Attack=Volume(config,"HitAttack",.85f);Sustain=Volume(config,"HitSustain",.35f);Sounds=config.Bind("Gameplay","HitSounds",true,"Enable gameplay hit sounds independently of editor preview.");HoldAttack=config.Bind("Gameplay","HoldAttack",true,"Play Hold head attack sound in gameplay.");SkyAttack=config.Bind("Gameplay","SkyAttackPolicy",1,new ConfigDescription("Sky head sound: 0 every segment, 1 native group capture, 2 off.",new AcceptableValueRange<int>(0,2)));}
  static ConfigEntry<float> Volume(ConfigFile c,string key,float value){return c.Bind("Gameplay",key,value,new ConfigDescription("Gameplay-only volume; editor and video export preferences are preserved.",new AcceptableValueRange<float>(0,1)));}
 }
}
